[CmdletBinding()]param([switch]$SelfTest,[string]$OutputOverride='',[switch]$SkipSignoff)
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $MyInvocation.MyCommand.Path;$toy=Join-Path $root 'validation/wp3-physics'
function Bad($m){throw "WP3 validation failed: $m"};function Req($c,$m){if(-not$c){Bad $m}}
function Near($a,$b,$rt,$at=1e-14){[Math]::Abs([double]$a-[double]$b)-le([double]$at+[double]$rt*[Math]::Abs([double]$b))}
function LogSlope($rows,$indices){$sx=0.0;$sy=0.0;$sxx=0.0;$sxy=0.0;$n=$indices.Count;foreach($i in $indices){$x=[Math]::Log(.5*([double]$rows[$i].gate_start_s+[double]$rows[$i].gate_stop_s));$y=[Math]::Log([Math]::Abs([double]$rows[$i].step_gate_average_v));$sx+=$x;$sy+=$y;$sxx+=$x*$x;$sxy+=$x*$y};return($n*$sxy-$sx*$sy)/($n*$sxx-$sx*$sx)}
function ReadJsonRetry($path){for($i=0;$i-lt20;$i++){try{return Get-Content -Raw -LiteralPath $path|ConvertFrom-Json}catch{if($i-eq19){throw};Start-Sleep -Milliseconds 10}}}
function FinitePositive($v){try{$d=[double]$v;return [double]::IsFinite($d)-and$d-gt0}catch{return $false}}
function ReadSignoffRoot($path){
 $expected=@('01-引言.md','02-全方法深度融合的底层逻辑与理论总纲.md','06-合成数据验证方案与验收设计.md','附录1-分矿种多方法融合定制化勘查模板.md','附录11-分勘查阶段标准化操作手册.md','附录13-岩性物性参数统计数据库.md','附录14-地质先验知识库.md','validation/wp3-physics/config.json','validation/wp3-physics/physics-contract.json','validation/wp3-physics/run-wp3-physics.ps1','validation/wp3-physics/oracle/wp3-oracle.ps1','validate-wp3.ps1','ACTIVE_MANIFEST')
 $all=@(Get-Content -LiteralPath $path);Req($all.Count-eq15-and$all[0]-ceq'# WP3 signoff input root v1'-and$all[1]-ceq'# SHA-256, UTF-8 path order fixed below')'signoff root header/line count'
 $lines=@($all[2..14]);for($i=0;$i-lt$expected.Count;$i++){Req($lines[$i]-cmatch'^([0-9a-f]{64})  (.+)$')"signoff root syntax $i";Req($Matches[2]-ceq$expected[$i])"signoff root member/order $i"}
 return $lines
}
function ParseSignoff($text){
 $keys=@('状态','输入版本','manifest SHA-256','成员清单内容根SHA-256','根清单文件SHA-256');$result=@{}
 foreach($key in $keys){$matches=[regex]::Matches($text,'(?m)^- '+[regex]::Escape($key)+'：(?:`([^`\r\n]+)`|([^`\r\n]+))\s*$');Req($matches.Count-eq1)"signoff field unique $key";$result[$key]=if($matches[0].Groups[1].Success){$matches[0].Groups[1].Value}else{$matches[0].Groups[2].Value.Trim()}}
 return $result
}
if($OutputOverride){$out=$OutputOverride}else{$p=ReadJsonRetry (Join-Path $toy 'active-output.json');Req($p.schema-eq'wp3-active-output-v1')'pointer schema';Req($p.version_path-match'^versions/[0-9]{8}T[0-9]{9}Z-[0-9a-f]{32}$')'pointer path';$out=[IO.Path]::GetFullPath((Join-Path $toy $p.version_path));$vr=[IO.Path]::GetFullPath((Join-Path $toy 'versions')).TrimEnd('\')+'\';Req($out.StartsWith($vr,[StringComparison]::OrdinalIgnoreCase))'pointer escape';Req((Get-FileHash -Algorithm SHA256 (Join-Path $out 'manifest.json')).Hash.ToLowerInvariant()-eq$p.manifest_sha256)'pointer hash'}
$cfg=gc -Raw (Join-Path $out 'config.json')|ConvertFrom-Json;$ct=gc -Raw (Join-Path $out 'physics-contract.json')|ConvertFrom-Json;$raw=gc -Raw (Join-Path $out 'raw-responses.json')|ConvertFrom-Json;$rs=gc -Raw (Join-Path $out 'results.json')|ConvertFrom-Json;$mf=gc -Raw (Join-Path $out 'manifest.json')|ConvertFrom-Json
Req($mf.schema-eq'wp3-manifest-v2'-and$mf.status-eq'Passed')'manifest schema/status';Req($mf.evidence_class-eq'Synthetic-run/Reference-regression')'evidence'
