Req($ct.case_tolerances.tem_halfspace.source-ceq'empymod==2.6.0 DLF key_201_2012; 5-point Gauss gate average; late-time -5/2 slope and finite-ramp/step convergence')'TEM tolerance source';Req($ct.case_tolerances.csamt_finite_source.source-ceq'empymod==2.6.0 finite bipole DLF; near/transition/far complex E/H and 100 ohm-m far-field limit')'CSAMT tolerance source';Req($ct.case_tolerances.wfem_axial.source-ceq'empymod==2.6.0 finite bipole DLF versus QWE transform cross-check; signed ABMN DC invariant')'WFEM tolerance source'
