Req(-not($cfg.tem.PSObject.Properties.Name-ccontains'characteristic_loop_length_m'))'independent TEM loop length rejected'
foreach($v in @($cfg.medium.sigma_s_m,$cfg.medium.epsilon_f_m,$cfg.medium.mu_h_m,$cfg.tem.current_a,$cfg.tem.equivalent_transmitter_area_m2,$cfg.tem.equivalent_receiver_area_m2,$cfg.tem.transmitter_turns,$cfg.tem.receiver_turns,$cfg.tem.loop_depth_m,$cfg.tem.ramp_s,$cfg.tem.gate_quadrature_order,$cfg.tem.small_loop_domain.ratio_max,$cfg.csamt.frequency_hz,$cfg.csamt.current_a,$cfg.csamt.electrode_depth_m,$cfg.csamt.source_depth_m,$cfg.csamt.receiver_z_m,$cfg.wfem.frequency_hz,$cfg.wfem.current_a,$cfg.dc.rho_ohm_m,$cfg.dc.current_a,$cfg.dc.am_m,$cfg.dc.an_m,$cfg.dc.bm_m,$cfg.dc.bn_m,$cfg.mt.rho_ohm_m,$cfg.mt.frequency_hz,$cfg.rock_fixture.temperature_k,$cfg.rock_fixture.curie_temperature_k,$cfg.rock_fixture.confining_pressure_pa,$cfg.rock_fixture.pore_pressure_pa)){Req(FinitePositive $v)'finite positive input domain'}
