foreach($b in @('induced_dominant','magnetization_known','low_latitude','stable_strike','local_threshold_calibrated')){Req($cfg.decisions.$b-is[bool])"decision boolean domain $b"};Req($cfg.decisions.mt_dimension-in@('2d','3d'))'MT dimension enum domain'
