foreach($g in @($cfg.tem.gates_s+$cfg.tem.asymptotic_check.gates_s)){Req($g.Count-eq2-and(FinitePositive $g[0])-and(FinitePositive $g[1])-and[double]$g[1]-gt[double]$g[0]-and[double]$g[0]-gt[double]$cfg.tem.ramp_s)'TEM gate domain'}
