$tMin=[double](($cfg.tem.gates_s|%{[double]$_[0]}|Measure-Object -Minimum).Minimum);$deltaPre=[Math]::Sqrt(4*$tMin/([double]$cfg.medium.mu_h_m*[double]$cfg.medium.sigma_s_m));$txLength=[Math]::Sqrt([double]$cfg.tem.equivalent_transmitter_area_m2/[Math]::PI);$rxLength=[Math]::Sqrt([double]$cfg.tem.equivalent_receiver_area_m2/[Math]::PI);$loopLength=[Math]::Max($txLength,$rxLength);$loopRatioPre=$loopLength/$deltaPre;Req($cfg.tem.small_loop_domain.ratio_definition-ceq'max(sqrt(A_tx/pi),sqrt(A_rx/pi))/delta_diff(t_min)'-and(FinitePositive $cfg.tem.small_loop_domain.ratio_max)-and[double]::IsFinite($loopRatioPre)-and$loopRatioPre-le[double]$cfg.tem.small_loop_domain.ratio_max)'small-loop gate before empymod'
$op=Join-Path ([IO.Path]::GetTempPath())('wp3-empymod-'+[guid]::NewGuid().ToString('N')+'.json');$oracleExe=Join-Path $toy '.venv-oracle/Scripts/python.exe';$oracleScript=Join-Path $toy 'oracle/empymod-frequency-oracle.py';try{& $oracleExe $oracleScript --config (Join-Path $out 'config.json') --output $op *> $null;Req($LASTEXITCODE-eq0-and(Test-Path $op))'empymod oracle exit/output';$o=gc -Raw $op|ConvertFrom-Json;Req($o.empymod_version-eq'2.6.0')'empymod version'}finally{if(Test-Path $op){Remove-Item $op}}
$rt=[double]$ct.relative_tolerance;$rtDc=[double]$ct.case_tolerances.dc_halfspace.relative;$rtMt=[double]$ct.case_tolerances.mt_1d.relative;$rtTem=[double]$ct.case_tolerances.tem_halfspace.relative;$rtCs=[double]$ct.case_tolerances.csamt_finite_source.relative;$rtWf=[double]$ct.case_tolerances.wfem_axial.relative;$dcRef=[double]$cfg.dc.rho_ohm_m/(2*[Math]::PI)*(1/[double]$cfg.dc.am_m-1/[double]$cfg.dc.an_m-1/[double]$cfg.dc.bm_m+1/[double]$cfg.dc.bn_m);$mtRef=[Numerics.Complex]::Sqrt([Numerics.Complex]::new(0,2*[Math]::PI*[double]$cfg.mt.frequency_hz*[double]$cfg.medium.mu_h_m*[double]$cfg.mt.rho_ohm_m));Req(Near $raw.dc.re $dcRef $rtDc)'DC mismatch';Req((Near $raw.mt.re $mtRef.Real $rtMt)-and(Near $raw.mt.im $mtRef.Imaginary $rtMt))'MT mismatch'
Req($raw.reference_engine-eq'empymod==2.6.0/dlf'-and$raw.tem_device-eq'magnetic-dipole/small-loop approximation'-and$raw.tem.Count-eq$o.tem_magnetic_dipole_small_loop_gate_average.Count)'TEM engine/count';$dd=[Math]::Sqrt(4*[double]$raw.small_loop_domain.t_min_s/([double]$cfg.medium.mu_h_m*[double]$cfg.medium.sigma_s_m));Req((Near $raw.small_loop_domain.delta_diff_m $dd 1e-12)-and(Near $raw.small_loop_domain.tx_characteristic_length_m $txLength 1e-12)-and(Near $raw.small_loop_domain.rx_characteristic_length_m $rxLength 1e-12)-and(Near $raw.small_loop_domain.characteristic_loop_length_m $loopLength 1e-12)-and(Near $raw.small_loop_domain.ratio ($loopLength/$dd) 1e-12)-and[double]$raw.small_loop_domain.ratio-le[double]$cfg.tem.small_loop_domain.ratio_max)'TEM small-loop domain';for($i=0;$i-lt$o.tem_magnetic_dipole_small_loop_gate_average.Count;$i++){Req((Near $raw.tem[$i].step_gate_average_v $o.tem_magnetic_dipole_small_loop_gate_average[$i].step_gate_average_v $rtTem)-and(Near $raw.tem[$i].ramp_gate_average_v $o.tem_magnetic_dipole_small_loop_gate_average[$i].ramp_gate_average_v $rtTem))'TEM gate average';Req([double]$raw.tem[$i].gate_stop_s-gt[double]$raw.tem[$i].gate_start_s-and$raw.tem[$i].nodes_s.Count-eq[int]$cfg.tem.gate_quadrature_order)'TEM gate metadata'};Req([double]$raw.tem[0].step_gate_average_v-gt[double]$raw.tem[1].step_gate_average_v-and[double]$raw.tem[1].step_gate_average_v-gt[double]$raw.tem[2].step_gate_average_v)'TEM early/late trend'
Req($raw.tem_asymptotic.Count-eq$o.tem_magnetic_dipole_late_time_asymptotic_gate_average.Count-and-not[string]::IsNullOrWhiteSpace([string]$cfg.tem.asymptotic_check.slope_tolerance_source)-and-not[string]::IsNullOrWhiteSpace([string]$cfg.tem.asymptotic_check.ratio_tolerance_source))'TEM asymptotic registration';for($i=0;$i-lt$raw.tem_asymptotic.Count;$i++){Req((Near $raw.tem_asymptotic[$i].step_gate_average_v $o.tem_magnetic_dipole_late_time_asymptotic_gate_average[$i].step_gate_average_v $rtTem)-and(Near $raw.tem_asymptotic[$i].ramp_gate_average_v $o.tem_magnetic_dipole_late_time_asymptotic_gate_average[$i].ramp_gate_average_v $rtTem))'TEM asymptotic raw';Req($raw.tem_asymptotic[$i].nodes_s.Count-eq[int]$cfg.tem.gate_quadrature_order)'TEM asymptotic nodes'};$fit=@($cfg.tem.asymptotic_check.fit_gate_indices|%{[int]$_});$slope=LogSlope $raw.tem_asymptotic $fit;Req([Math]::Abs($slope-[double]$cfg.tem.asymptotic_check.slope_target)-le[double]$cfg.tem.asymptotic_check.slope_absolute_tolerance)'TEM late-time -5/2 slope';$prev=[double]::PositiveInfinity;foreach($i in $fit){$e=[Math]::Abs([double]$raw.tem_asymptotic[$i].ramp_gate_average_v/[double]$raw.tem_asymptotic[$i].step_gate_average_v-1);Req($e-lt$prev)'TEM ramp/step convergence trend';$prev=$e};Req($prev-le[double]$cfg.tem.asymptotic_check.ramp_step_ratio_terminal_absolute_tolerance)'TEM ramp/step terminal convergence'
