$docs=@('01-引言.md','02-全方法深度融合的底层逻辑与理论总纲.md','06-合成数据验证方案与验收设计.md','附录1-分矿种多方法融合定制化勘查模板.md','附录11-分勘查阶段标准化操作手册.md','附录13-岩性物性参数统计数据库.md','附录14-地质先验知识库.md');$text=@{};foreach($d in $docs){$text[$d]=gc -Raw (Join-Path $root $d)}
